const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.game}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const people={
 '林墨':{cls:'me',id:'linmo#1000',online:true},'阿岚':{cls:'alan',id:'alan#1001',online:true,roomId:'weekend'},'青禾':{cls:'qing',id:'qinghe#1002',online:true,roomId:'star'},'北屿':{cls:'bei',id:'beiyu#1003',online:true,roomId:'weekend'},'洛川':{cls:'luo',id:'luochuan#1004',online:false},'苏叶':{cls:'mo',id:'suye#1005',online:true,roomId:'racing'}
};
const avatar=(name,online=people[name]?.online)=>`<span class="avatar ${people[name]?.cls||'mo'} ${online?'online':''}">${esc(name[0])}</span>`;
const rooms=[
 {id:'weekend',name:'周末方块局',game:'MINECRAFT',desc:'生存建造',cover:'cubes',groupId:'expedition',host:'阿岚',open:true,members:[{name:'阿岚',ip:'10.66.0.10',voice:'connected',speaking:true},{name:'北屿',ip:'10.66.0.11',voice:'connected',muted:true},{name:'青禾',ip:'10.66.0.13',voice:'connected'}],messages:[{id:'r1',user:'阿岚',time:'19:42',text:'新家这边我把仓库补好了，今晚一起下矿？'},{id:'r2',user:'北屿',time:'19:44',text:'可以，我带两组火把。直接连阿岚的地址就行吧？'},{id:'r3',user:'阿岚',time:'19:45',text:'对，进房后复制我的虚拟 IP，在游戏里直接连接。'}]},
 {id:'star',name:'星野探索队',game:'星际边境',desc:'探索未知星系',cover:'space',groupId:'observatory',host:'青禾',open:true,members:[{name:'青禾',ip:'10.66.1.10',voice:'connected'},{name:'洛川',ip:'10.66.1.11',voice:'connected'}],messages:[{id:'s1',user:'青禾',time:'19:30',text:'今晚一起去看新星球。'}]},
 {id:'racing',name:'午夜竞速场',game:'极限竞速',desc:'环岛耐力赛',cover:'racing',groupId:'racing',host:'苏叶',open:true,members:[{name:'苏叶',ip:'10.66.2.10',voice:'connected'},{name:'北屿',ip:'10.66.2.11',voice:'connected'}],messages:[{id:'c1',user:'苏叶',time:'19:20',text:'还差两位，九点开始。'}]}
];
