 {id:'expedition',name:'周末远征队',icon:'远',members:['林墨','阿岚','北屿','青禾','洛川','苏叶'],roomIds:['weekend'],messages:[{id:'g1',user:'阿岚',time:'19:32',text:'今晚方块局已开，直接去大厅就能加入。'},{id:'g2',user:'青禾',time:'19:35',text:'收到！我吃完晚饭来。'}]},
 {id:'workshop',name:'像素工坊',icon:'像',members:['林墨','阿岚','北屿'],roomIds:[],messages:[{id:'w1',user:'阿岚',time:'18:30',text:'新的建筑参考图片发到群里了。'}]},
 {id:'racing',name:'深夜车队',icon:'车',members:['林墨','苏叶','北屿','洛川'],roomIds:['racing'],messages:[{id:'d1',user:'苏叶',time:'19:10',text:'今晚九点，环岛耐力赛。'}]},
 {id:'observatory',name:'星野观测站',icon:'星',members:['林墨','青禾','洛川'],roomIds:['star'],messages:[{id:'o1',user:'青禾',time:'19:15',text:'先组队，再决定探索路线。'}]}
