const state={authenticated:true,authMode:'login',view:'lobby',roomTab:'chat',roomId:null,sessionStatus:'idle',voice:'disconnected',network:'disconnected',muted:false,deafened:false,speaking:false,volume:80,friendFilter:'online',friendQuery:'',friends:['阿岚','青禾','北屿','苏叶'],incomingRequests:['洛川'],outgoingRequests:[],invites:[],modal:null,toast:'',groupId:'expedition',memberVolumes:{},drafts:{room:{},group:{}},chatScroll:{room:{},group:{}},joinedAt:null,settingsTab:'voice',settings:{speaking:true,recover:true,inputDevice:'默认麦克风（模拟）',outputDevice:'头戴式耳机（模拟）'},nextId:10};
Object.defineProperty(state,'joined',{get(){return ['joining','active'].includes(state.sessionStatus)}});
window.state=state;window.rooms=rooms;window.groups=groups;
const me='林墨';
const currentRoom=()=>rooms.find(r=>r.id===state.roomId)||null;
const currentGroup=()=>groups.find(g=>g.id===state.groupId);
const roomMembers=r=>r?.members||[];
const myMember=r=>roomMembers(r).find(m=>m.name===me);
const personStatus=n=>{const p=people[n];if(!p?.online)return '离线';const room=rooms.find(item=>item.members.some(member=>member.name===n)&&isGroupMember(item.groupId));return room?`${room.name} · ${room.game}`:'在线'};
const onlineFriends=()=>state.friends.filter(n=>people[n]?.online);
const timeNow=()=>new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});
const canModerate=(groupId=state.groupId)=>['owner','admin'].includes(groupRole(groupId));
function toast(text){state.toast=text;renderToast();clearTimeout(toast.timer);toast.timer=setTimeout(()=>{state.toast='';renderToast()},2800)}
function renderToast(){document.getElementById('toast').innerHTML=state.toast?`<div class="toast">${esc(state.toast)}</div>`:''}
function openModal(title,desc,body,actions=''){if(!state.modal){state.returnFocus=document.activeElement;const action=state.returnFocus?.dataset.action;state.returnFocusSelector=action?`[data-action="${action}"]`:null;}state.modal={title,desc,body,actions};renderModal();focusModal()}
function closeModal(){discardMediaDraft();state.modal=null;renderModal();document.getElementById('app').inert=false;if(state.returnFocus?.isConnected)state.returnFocus.focus();else if(state.returnFocusSelector)document.querySelector(state.returnFocusSelector)?.focus();state.returnFocus=null}
function renderModal(){const m=state.modal;document.getElementById('app').inert=!!m;document.getElementById('modal').innerHTML=m?`<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" tabindex="-1" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${m.title}</h2><p>${m.desc||''}</p></div><button class="icon-button" data-action="modal-close" aria-label="关闭">${icon('close',18)}</button></div><div>${m.body}</div>${m.actions?`<div class="modal-actions">${m.actions}</div>`:''}</section></div>`:'';labelFields();if(state.mediaDraft){const preview=document.getElementById('media-preview'),caption=document.getElementById('media-caption');if(preview&&state.pendingMedia)preview.innerHTML=mediaPreview(state.pendingMedia);if(caption)caption.value=state.mediaDraft.caption;updateMediaTransfer()}if(m)focusModal()}
function topbar(){return `<header class="titlebar"><div class="brand"><span class="brand-mark"></span><span class="brand-name">织界<small>WEAVORA</small></span></div><span class="window-title">和喜欢的人，玩同一个世界</span><div class="top-actions"><span class="connection-pill"><i class="status-dot"></i>${state.service==='offline'?'服务不可达 · 模拟':'原型模拟数据'}</span><div class="window-controls"><button data-action="window-control" data-window="minimize" aria-label="最小化">—</button><button data-action="window-control" data-window="maximize" aria-label="最大化">□</button><button data-action="window-control" data-window="close" aria-label="关闭">×</button></div></div></header>`}
function rail(){const item=(view,ico,label)=>`<button class="nav-item ${state.view===view||(view==='groups'&&state.view==='groupChat')?'active':''}" data-action="nav" data-view="${view}" aria-label="${label}">${icon(ico)}<span>${label}</span></button>`;return `<aside class="rail"><nav aria-label="主导航">${item('lobby','home','大厅')}${item('friends','users','好友')}${item('groups','messages','群组')}<div class="rail-separator"></div><button class="nav-item" data-action="create-room" aria-label="创建房间">${icon('plus')}<span>创建</span></button></nav><div class="rail-bottom"><button class="nav-item" data-action="help" aria-label="联机帮助">${icon('help')}</button><button class="nav-item ${state.view==='settings'?'active':''}" data-action="nav" data-view="settings" aria-label="设置">${icon('settings')}</button><button class="mini-me" data-action="profile" aria-label="林墨的账号">林</button></div></aside>`}
function statusChip(type,value){return renderChannelStatus(type,value)}
function voiceDock(){if(!state.joined)return '';const r=currentRoom();return `<div class="voice-dock"><button class="voice-now" data-action="open-room" data-room="${r.id}" style="border:0;background:transparent;color:inherit;text-align:left;padding:0"><span class="voice-room-icon">${icon('headphones')}</span><span><strong>${esc(r.name)}</strong><small>${state.sessionStatus==='joining'?'正在加入房间…':`${channelLabel('voice',state.voice)} · ${channelLabel('network',state.network)}`}</small></span></button><div class="voice-controls">${state.speaking&&state.settings.speaking?'<div class="wave" aria-label="正在发言"><i></i><i></i><i></i><i></i><i></i></div>':''}<button class="voice-button ${state.muted?'off':''}" data-action="toggle-mute" title="${state.muted?'取消静音':'麦克风静音'}" aria-pressed="${state.muted}">${icon(state.muted?'micOff':'mic')}<span>${state.muted?'已静音':state.speaking?'发言中':'已开麦'}</span></button><button class="voice-button ${state.deafened?'off':''}" data-action="toggle-deafen" title="${state.deafened?'恢复接收':'关闭接收'}" aria-label="${state.deafened?'恢复接收':'关闭接收'}" aria-pressed="${state.deafened}">${icon('headphones')}</button><button class="voice-button" data-action="audio-settings" title="语音设置" aria-label="语音设置">${icon('settings')}</button><button class="voice-button leave" data-action="leave-room" title="离开房间" aria-label="离开房间">${icon('phoneOff')}</button></div><div class="voice-right">${statusChip('network',state.network)}</div></div>`}
function friendItem(name,status=personStatus(name)){return `<div class="friend-item"><button data-action="friend-profile" data-name="${name}" style="display:flex;align-items:center;gap:10px;flex:1;min-width:0;border:0;background:transparent;color:inherit;text-align:left;padding:0">${avatar(name)}<span class="friend-copy"><strong>${name}</strong><small>${esc(status)}</small></span></button><button class="icon-button" data-action="invite-friend" data-name="${name}" title="邀请组队">${icon('plus',15)}</button></div>`}
function aside(){const online=onlineFriends();return `<aside class="right-panel"><div class="panel-title"><h2>在线好友</h2><span class="count-badge">${online.length} 在线</span></div><div class="friend-list">${online.map(n=>friendItem(n)).join('')||'<div class="empty-state">暂无在线好友</div>'}</div><button class="button ghost" style="width:100%;margin-top:10px" data-action="nav" data-view="friends">查看全部好友 ${icon('arrow',14)}</button><div class="aside-divider"></div><div class="tip-card"><strong>联机小贴士</strong><br>进入房间后，在「联机」页复制实际游戏主机成员虚拟 IP，再回到游戏中直接连接。</div></aside>`}
function roomCard(r){const isCurrent=state.joined&&r.id===state.roomId;return `<article class="room-card"><div class="room-cover ${r.cover}"><span class="game-chip">${esc(r.game)}</span><span class="room-capacity">${r.members.length} / 16</span></div><div class="room-body"><div class="room-title-row"><h3>${esc(r.name)}</h3><span class="status-dot" title="${r.open?'开放加入':'暂停加入'}"></span></div><p>${esc(r.desc)} · ${r.open?(r.members.length?'活动中':'等待队友'):'暂停加入'}</p><div class="room-footer">${canManageRoom(r)?`<button class="icon-button" data-action="room-settings" data-room="${r.id}" aria-label="管理 ${esc(r.name)}">${icon('settings',16)}</button>`:''}<div class="avatar-stack">${r.members.map(m=>avatar(m.name)).join('')}</div><button class="join-arrow" data-action="${isCurrent?'open-room':'join-room'}" data-room="${r.id}" aria-label="${isCurrent?'回到':'加入'} ${esc(r.name)}">${icon('arrow',16)}</button></div></div></article>`}
function activeHero(){if(!state.joined)return '';const r=currentRoom();return `<section class="hero"><div class="hero-copy"><span class="live-label"><i></i> YOUR PARTY IS LIVE</span><h2>${esc(r.name)}</h2><span class="hero-game">${esc(r.game)} · ${esc(r.desc)}</span><div class="hero-meta"><div class="avatar-stack">${r.members.map(m=>avatar(m.name)).join('')}</div><span>${r.members.length} 位玩家正在房间里</span></div><div class="hero-cta"><button class="button primary" data-action="open-room" data-room="${r.id}">回到房间 ${icon('arrow',15)}</button><span class="link-note">${state.sessionStatus==='joining'?'正在建立连接':'已加入 · 可跨页面保持语音'}</span></div></div><div class="network-visual" style="display:flex;align-items:center;justify-content:center"><div style="text-align:center"><div class="network-core" style="position:static;margin:0 auto 18px">${icon('network',28)}</div><strong>先连虚拟网络，再连语音</strong><p class="link-note" style="margin-top:10px">网络中断会影响语音；音频故障可单独重试</p></div></div></section>`}
function lobby(){return `<div class="content-grid"><main class="main-scroll"><div class="page-heading"><div><div class="eyebrow">PLAYER LOBBY · 玩家大厅</div><h1>别等开局，先聚在一起。</h1><p>语音、聊天和虚拟局域网，在一个房间里就绪。</p></div><div class="heading-actions"><button class="button" data-action="join-code">加入房间</button><button class="button primary" data-action="create-room">${icon('plus',16)} 创建房间</button></div></div>${activeHero()}<div class="section-head"><div><h2>${state.joined?'其他群内房间':'选择一个房间，准备开局'}</h2><p>和群友会合，一起开局。</p></div><button class="text-button" data-action="create-room">创建房间 +</button></div><div class="room-grid">${rooms.filter(room=>isGroupMember(room.groupId)).map(roomCard).join('')||'<div class="empty-state">还没有可加入的房间，请先创建群组或接受群邀请。</div>'}</div></main>${aside()}</div>`}
function playerTile(m){const r=currentRoom(),muted=m.name===me?state.muted:!!m.muted,speaking=m.name===me?state.speaking:!!m.speaking;return `<article class="player-tile ${speaking&&state.settings.speaking?'speaking':''}">${m.name===r.host?'<span class="host-tag">HOST</span>':m.name===me?'<span class="host-tag">YOU</span>':''}<button class="icon-button tile-more" data-action="player-settings" data-name="${m.name}" aria-label="${m.name} 的设置">${icon('more',17)}</button>${avatar(m.name)}<div class="player-name"><div><strong>${m.name}${m.name===me?'（你）':''}</strong><small>${m.voice!=='connected'?channelLabel('voice',m.voice):muted?'麦克风已关闭':speaking?'正在说话':'语音已连接'}</small></div><span class="player-state ${muted?'muted':''}">${icon(muted?'micOff':'mic',15)}</span></div></article>`}
function mediaPreview(media){if(!media)return '';return media.type==='video'?`<video class="message-media" src="${esc(media.url)}" controls preload="metadata" aria-label="${esc(media.name)}"></video>`:`<img class="message-media" src="${esc(media.url)}" alt="${esc(media.name)}">`}
function messageHtml(m,scope){const deleted=m.deleted;return `<div class="message ${scope==='group'&&m.user===me?'own':''}" data-message-id="${m.id}">${avatar(m.user)}<div class="message-content"><div class="message-meta"><strong>${esc(m.user)}</strong><time>${m.time}</time>${!deleted&&(m.user===me||canModerate(scope==='room'?currentRoom()?.groupId:state.groupId))?`<button class="icon-button message-more" data-action="delete-message" data-scope="${scope}" data-id="${m.id}" aria-label="删除消息">${icon('more',15)}</button>`:''}</div>${deleted?'<div class="message-text">此消息已被删除</div>':`${m.text?`<div class="message-text">${esc(m.text)}</div>`:''}${mediaPreview(m.media)}${messageReceipt(m)}`}</div></div>`}
function chatPanel(){const r=currentRoom();return `<div class="chat-scroll">${syncNotice('room')}${r.messages.map(m=>messageHtml(m,'room')).join('')}</div><form class="chat-compose" data-form="room-message"><button class="icon-button" type="button" data-action="attach-media" data-scope="room" aria-label="发送图片或视频">${icon('plus',17)}</button><input id="room-message-input" data-input="room-draft" value="${esc(state.drafts.room[r.id]||'')}" aria-label="房间消息" placeholder="发消息给房间里的队友…" autocomplete="off"><button class="icon-button" type="submit" aria-label="发送">${icon('send',16)}</button></form>`}
function networkPanel(){const r=currentRoom();if(state.network!=='connected')return `<div class="network-panel"><div class="network-hero">${statusChip('network',state.network)}<h3>${channelLabel('network',state.network)}</h3><p>${esc(state.channelErrors.network||'连接成功后即可查看和复制成员地址。')}</p></div></div>`;return `<div class="network-panel"><div class="network-hero">${statusChip('network',state.network)}<h3>你们已经在同一个网络里</h3><p>织界房主不一定是游戏内主机，请复制实际游戏主机成员的虚拟 IP。</p></div><div class="step-list"><div class="step"><span class="step-num">1</span><div><strong>确认谁在游戏里创建主机</strong><p>请创建游戏世界的队友确认。</p></div></div><div class="step"><span class="step-num">2</span><div><strong>复制该成员的虚拟 IP</strong><p>在下方找到这位队友的地址。</p></div></div><div class="step"><span class="step-num">3</span><div><strong>在游戏里直接连接</strong><p>粘贴地址；如需端口，按游戏规则补充。</p></div></div></div><div class="member-ip-heading"><strong>成员虚拟 IP</strong><span>${r.members.length} 个可用地址</span></div><div class="member-ip-list">${r.members.map(memberIpRow).join('')}</div><button class="button ghost small" style="margin-top:14px" data-action="network-help">连接失败怎么办？</button></div>`}
function memberIpRow(m){return `<div class="member-ip-row">${avatar(m.name)}<div class="member-ip-copy"><strong>${esc(m.name)}${m.name===me?'（你）':''}</strong><span class="ip-address">${m.ip}</span></div><button class="copy-button" data-action="copy-ip" data-ip="${m.ip}" data-name="${esc(m.name)}" aria-label="复制 ${esc(m.name)} 的虚拟 IP">${icon('copy',12)} 复制</button></div>`}
function membersPanel(){const r=currentRoom();return `<div class="network-panel"><div class="panel-title"><h2>房间成员</h2><span class="count-badge">${r.members.length} / 16</span></div>${r.members.map(m=>friendItem(m.name,`${m.name===r.host?'房主 · ':''}${m.voice==='connected'?'语音已连接':'语音未连接'}`)).join('')}<button class="button primary" style="width:100%;margin-top:16px" data-action="invite-friend">${icon('userPlus',15)} 邀请队友</button></div><div></div>`}
function roomView(){const r=currentRoom();if(!r)return lobby();return `<div class="room-layout"><main class="room-stage"><div class="room-top"><div class="room-heading"><button class="back-button" data-action="nav" data-view="lobby" aria-label="返回大厅">${icon('back',17)}</button><div><h1>${esc(r.name)}</h1><p>${esc(r.game)} · ${esc(r.desc)} · ${r.members.length} / 16</p></div></div><div class="room-flags">${statusChip('voice',state.voice)}${statusChip('network',state.network)}${canManageRoom(r)?`<button class="icon-button" data-action="room-settings" data-room="${r.id}" title="房间设置" aria-label="房间设置">${icon('settings',17)}</button>`:''}</div></div><div class="party-grid">${r.members.map(playerTile).join('')}<article class="player-tile empty-player"><button data-action="invite-friend">${icon('userPlus',24)}<span>邀请队友</span></button></article></div></main><aside class="room-side"><div class="side-tabs">${[['chat','聊天'],['network','联机'],['members',`成员 ${r.members.length}`]].map(([id,label])=>`<button class="side-tab ${state.roomTab===id?'active':''}" data-action="room-tab" data-tab="${id}">${label}</button>`).join('')}</div>${state.roomTab==='chat'?chatPanel():state.roomTab==='network'?networkPanel():membersPanel()}</aside></div>`}
function friendsView(){const query=state.friendQuery.trim().toLowerCase();const filtered=state.friends.filter(n=>(state.friendFilter==='all'||people[n].online)&&(!query||n.toLowerCase().includes(query)||people[n].id.toLowerCase().includes(query)));return `<main class="main-scroll"><div class="center-panel"><div class="page-heading"><div><div class="eyebrow">FRIENDS · 好友</div><h1>下次开局，不用再找人。</h1><p>看看谁在线，邀请好友一起玩。</p></div><button class="button primary" data-action="add-friend">${icon('userPlus',16)} 添加好友</button></div><div class="filter-row"><input class="search-field" data-input="friend-search" value="${esc(state.friendQuery)}" placeholder="搜索昵称或账号 ID" aria-label="搜索好友"><div class="segmented"><button class="${state.friendFilter==='online'?'active':''}" data-action="friend-filter" data-filter="online">在线 ${onlineFriends().length}</button><button class="${state.friendFilter==='all'?'active':''}" data-action="friend-filter" data-filter="all">全部 ${state.friends.length}</button><button data-action="friend-requests">待处理 <span style="color:var(--accent)">${state.incomingRequests.length}</span></button></div></div><section class="friends-table">${filtered.length?filtered.map(n=>`<div class="friend-row">${avatar(n)}<div class="friend-copy"><strong>${n}</strong><small>${esc(personStatus(n))} · ${people[n].id}</small></div><button class="button ghost" data-action="invite-friend" data-name="${n}">${icon('plus',14)} 邀请组队</button><button class="icon-button" data-action="friend-profile" data-name="${n}" aria-label="${n} 的资料">${icon('more',17)}</button></div>`).join(''):'<div class="empty-state">没有找到匹配的好友，可尝试完整昵称或账号 ID。</div>'}</section></div></main>`}
function groupsView(){const pending=state.invites.filter(invite=>invite.name===me&&invitationStatus(invite)==='pending').length;return `<main class="main-scroll"><div class="center-panel"><div class="page-heading"><div><div class="eyebrow">GROUPS · 私密群组</div><h1>朋友常在，热闹不散。</h1><p>和熟悉的朋友，约好下一局。</p></div><button class="button primary" data-action="create-group">${icon('plus',16)} 创建群组</button></div><div class="group-list-toolbar"><h2>我的群组</h2><button class="button ghost small group-invites" data-action="incoming-invites" aria-label="群邀请${pending?`，${pending} 条待处理`: ''}">${icon('userPlus',15)} 群邀请${pending?`<span class="count-badge">${pending}</span>`:''}</button></div><div class="group-grid">${groups.filter(group=>isGroupMember(group.id)).map(g=>`<button class="group-card" data-action="open-group" data-group="${g.id}"><div class="group-card-top"><span class="group-icon">${esc(g.icon)}</span>${icon('arrow',17)}</div><h3>${esc(g.name)}</h3><p>${g.members.length} 位成员 · ${g.roomIds.length} 个游戏房间</p><div class="group-card-foot"><span>私密群组</span><span>进入聊天 →</span></div></button>`).join('')||'<div class="empty-state">暂无群组，可创建私密群组，或请朋友发送邀请。</div>'}</div></div></main>`}
function groupChatView(){const g=currentGroup(),online=g.members.filter(n=>people[n]?.online).length,groupRooms=rooms.filter(r=>g.roomIds.includes(r.id));return `<div class="group-chat"><header class="group-chat-head"><button class="back-button" data-action="nav" data-view="groups" aria-label="返回群组列表">${icon('back',16)}</button><div><h1>${esc(g.name)}</h1><p>${g.members.length} 位成员 · ${online} 人在线 · ${esc(g.desc||'私密群组')}</p></div><button class="button ghost small" style="margin-left:auto" data-action="group-manage">群组管理</button></header><div class="group-chat-content"><div class="group-chat-body">${syncNotice('group')}${g.messages.map(m=>messageHtml(m,'group')).join('')}</div><aside class="group-room-list"><div class="panel-title"><h2>游戏房间</h2><span class="count-badge">${groupRooms.length}</span></div><p>和群友从聊天直接进入同一局。</p>${groupRooms.map(r=>`<article class="group-room-card"><span class="game-chip-static">${esc(r.game)}</span><h3>${esc(r.name)}</h3><div><span>${r.members.length} / 16 · ${r.open?'进行中':'暂停加入'}</span><button class="join-arrow" data-action="${state.joined&&state.roomId===r.id?'open-room':'join-room'}" data-room="${r.id}" aria-label="${state.joined&&state.roomId===r.id?'回到':'加入'} ${esc(r.name)}">${icon('arrow',15)}</button></div></article>`).join('')||'<div class="group-room-empty">还没有游戏房间<br>创建后会显示在这里。</div>'}<button class="button ghost small" data-action="create-room">${icon('plus',13)} 创建群房间</button></aside></div><form class="group-compose" data-form="group-message"><button class="icon-button" type="button" data-action="attach-media" data-scope="group" aria-label="发送图片或视频">${icon('plus',17)}</button><input id="group-message-input" data-input="group-draft" value="${esc(state.drafts.group[g.id]||'')}" placeholder="发消息到 ${esc(g.name)}，或分享图片与视频" aria-label="群组消息" autocomplete="off"><button class="button primary" type="submit">${icon('send',15)} 发送</button></form></div>`}
function voiceSettingsPanel(){return `<section class="settings-card"><h2>语音设备</h2><div class="setting-row"><div><strong>输入设备</strong><small>选择队友听到的麦克风</small></div><select data-change="input-device" aria-label="输入设备"><option ${state.settings.inputDevice==='默认麦克风（模拟）'?'selected':''}>默认麦克风（模拟）</option><option ${state.settings.inputDevice==='USB 麦克风（模拟）'?'selected':''}>USB 麦克风（模拟）</option></select></div><div class="setting-row"><div><strong>输出设备</strong><small>选择游戏语音播放设备</small></div><select data-change="output-device" aria-label="输出设备"><option ${state.settings.outputDevice==='头戴式耳机（模拟）'?'selected':''}>头戴式耳机（模拟）</option><option ${state.settings.outputDevice==='默认扬声器（模拟）'?'selected':''}>默认扬声器（模拟）</option></select></div><div class="setting-row"><div><strong>总音量 · <span id="master-volume-label">${state.volume}%</span></strong><small>只调整本地接收音量</small></div><input class="setting-range" type="range" min="0" max="100" value="${state.volume}" data-input="volume" aria-label="总音量"></div><div class="setting-row"><div><strong>麦克风测试</strong><small>原型不会采集或播放真实音频</small></div><button class="button small" data-action="device-test">测试设备</button></div></section><section class="settings-card"><h2>语音体验</h2><div class="setting-row"><div><strong>说话状态提示</strong><small>在头像周围显示音量反馈</small></div><button class="toggle ${state.settings.speaking?'on':''}" data-action="toggle-setting" data-setting="speaking" aria-label="切换说话状态提示" aria-pressed="${state.settings.speaking}"></button></div><div class="setting-row"><div><strong>自动恢复连接</strong><small>断线 60 秒内自动重连并保留原 IP</small></div><button class="toggle ${state.settings.recover?'on':''}" data-action="toggle-setting" data-setting="recover" aria-label="切换自动恢复" aria-pressed="${state.settings.recover}"></button></div></section>`}
function accountSettingsPanel(){return `<section class="settings-card"><h2>账号与设备</h2><div class="modal-note">同一账号只能在一台电脑中加入房间。</div><div class="setting-row"><div><strong>林墨</strong><small>demo@example.test · 已验证</small></div><span class="status-chip good">账号有效</span></div><div class="setting-row"><div><strong>此电脑</strong><small>Windows · ${state.joined?'当前活动设备':'已登录，未入房'}</small></div><span class="status-chip">${state.joined?'活动中':'未入房'}</span></div><div class="setting-row"><div><strong>另一台电脑</strong><small>macOS · ${state.activeDevice==='另一台电脑'?'活动中（模拟）':'已登录，未入房'}</small></div><button class="button small" data-action="device-transfer" ${state.joined?'':'disabled'}>转移活动</button></div></section>`}
function supportSettingsPanel(){return `<section class="settings-card"><h2>安装与支持</h2><div class="modal-note">平台安装与游戏兼容性尚未验证。</div><div class="setting-row"><div><strong>Windows 10 / 11 x64</strong><small>NSIS · 权限条件待验证</small></div><span class="status-chip">未验证</span></div><div class="setting-row"><div><strong>macOS 13+</strong><small>Intel / Apple Silicon</small></div><span class="status-chip">未验证</span></div><div class="setting-row"><div><strong>Ubuntu 22.04 / 24.04</strong><small>x86_64 · 桌面环境待验证</small></div><span class="status-chip">未验证</span></div></section>`}
function settingsView(){const tab=state.settingsTab,content=tab==='account'?accountSettingsPanel():tab==='support'?supportSettingsPanel():voiceSettingsPanel();return `<main class="main-scroll"><div class="center-panel"><div class="page-heading"><div><div class="eyebrow">PREFERENCES · 设置</div><h1>按你的方式，舒服地玩。</h1><p>调整语音设备，管理账号。</p></div></div><div class="settings-grid"><nav class="settings-menu" role="tablist" aria-label="设置分类"><button role="tab" aria-selected="${tab==='voice'}" class="${tab==='voice'?'active':''}" data-action="settings-tab" data-tab="voice">语音与设备</button><button role="tab" aria-selected="${tab==='account'}" class="${tab==='account'?'active':''}" data-action="account-settings">账号与设备</button><button role="tab" aria-selected="${tab==='support'}" class="${tab==='support'?'active':''}" data-action="support-matrix">安装与支持</button><button data-action="logout">退出登录</button></nav><div class="settings-content" role="tabpanel" aria-label="${tab==='account'?'账号与设备':tab==='support'?'安装与支持':'语音与设备'}">${content}</div></div></div></main>`}
function render(){if(state.joined&&(!isGroupMember(currentRoom()?.groupId)||!myMember(currentRoom())))revokeActivity();if(state.view==='groupChat'&&!isGroupMember(state.groupId))state.view='groups';const app=document.getElementById('app');if(!state.authenticated){app.innerHTML=authView();renderModal();return}let content=state.view==='room'?roomView():state.view==='friends'?friendsView():state.view==='groups'?groupsView():state.view==='groupChat'?groupChatView():state.view==='settings'?settingsView():lobby();app.innerHTML=`<div class="app">${topbar()}<div class="workspace">${rail()}<div class="content-shell ${state.joined?'':'no-voice'}">${content}${voiceDock()}</div></div></div>`;renderModal();const roomChat=document.querySelector('.chat-scroll'),groupChat=document.querySelector('.group-chat-body');if(roomChat)roomChat.scrollTop=state.chatScroll.room[state.roomId]||0;if(groupChat)groupChat.scrollTop=state.chatScroll.group[state.groupId]||0}
function scrollChatToBottom(scope){setTimeout(()=>{const el=document.querySelector(scope==='room'?'.chat-scroll':'.group-chat-body'),id=scope==='room'?state.roomId:state.groupId;if(!el||!id)return;el.scrollTop=el.scrollHeight;state.chatScroll[scope][id]=el.scrollTop},0)}
function createRoomModal(){showCreateRoom()}
function joinModal(id){showJoinRoom(id)}
function joinRoom(id){return enterRoom(id,document.getElementById('room-password')?.value||'')}
function leaveRoom(){revokeActivity();closeModal();render();toast('已离开房间。')}
function logout(){revokeActivity();state.authenticated=false;state.authMode='login';state.toast='';clearTimeout(toast.timer);renderToast();closeModal();render()}
function helpModal(network=false){openModal(network?'虚拟网络连接帮助':'三步，进入同一个世界','仅连接房间成员的本机服务，不代理互联网或转发其他局域网设备。','<div class="step-list"><div class="step"><span class="step-num">1</span><div><strong>检查能否加入房间</strong><p>确认已加入所属群组，房间开放且未满员；如另一台电脑正在房间中，请先转移活动。</p></div></div><div class="step"><span class="step-num">2</span><div><strong>分别检查语音与网络</strong><p>语音依赖虚拟网络。音频故障可单独重试，直连失败时没有服务器中继回退。</p></div></div><div class="step"><span class="step-num">3</span><div><strong>复制实际游戏主机成员 IP，在游戏内直接连接</strong><p>如需端口，请向创建游戏的队友确认；重新入房后请核对 IP 是否变化。</p></div></div></div>',`<button class="button primary" data-action="modal-close">知道了</button>`)}
function groupManageModal(){showGroupManagement()}
function inviteModal(name){const choices=name?[name]:state.friends;openModal('邀请队友','对方须先接受群邀请，再按房间规则加入。',`<div class="field"><label>选择好友</label><select id="invite-name">${choices.map(n=>`<option>${n}</option>`).join('')}</select></div><div class="field"><label>目标房间</label><select id="invite-room">${rooms.filter(room=>isGroupMember(room.groupId)).map(r=>`<option value="${r.id}" ${r.id===state.roomId?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div>`,`<button class="button" data-action="modal-close">取消</button><button class="button primary" data-action="confirm-invite">发送邀请</button>`)}
function mediaModal(scope){openMediaDraft(scope)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='nav'){state.view=b.dataset.view;state.modal=null;render()}
 else if(a==='window-control'){const action=b.dataset.window;if(action==='close')openModal('关闭织界？','浏览器原型不会关闭真实窗口。','',`<button class="button primary" data-action="modal-close">继续使用</button>`);else toast(`${action==='minimize'?'最小化':'最大化'}由正式桌面客户端执行，浏览器原型不操作真实窗口。`)}
 else if(a==='open-room'){const id=b.dataset.room;if(state.joined&&id===state.roomId){state.view='room';state.roomTab='chat';closeModal();render()}else joinModal(id)}
 else if(a==='join-room'){joinModal(b.dataset.room)}
 else if(a==='confirm-join'){joinRoom(b.dataset.room)}
 else if(a==='create-room'){createRoomModal()}
 else if(a==='join-code'){openModal('加入游戏房间','输入朋友分享的房间邀请码。','<div class="field"><label>邀请码</label><input id="join-code" value="WV-7K2M-9P" autocomplete="off"></div>',`<button class="button" data-action="modal-close">取消</button><button class="button primary" data-action="confirm-join-code">加入房间</button>`)}
 else if(a==='room-tab'){state.roomTab=b.dataset.tab;render()}
 else if(a==='attach-media'){mediaModal(b.dataset.scope)}
 else if(a==='confirm-media'){startMediaDelivery()}
 else if(a==='retry-media'){startMediaDelivery()}
 else if(a==='review-media-outcome'&&reviewEnabled){state.mediaReviewOutcome=b.dataset.outcome;toast('下一次发送：'+b.textContent)}
 else if(a==='toggle-mute'){state.muted=!state.muted;const m=myMember(currentRoom());if(m)m.muted=state.muted;if(state.muted)state.speaking=false;render()}
 else if(a==='toggle-deafen'){state.deafened=!state.deafened;render()}
 else if(a==='leave-room'){openModal('离开当前房间？','离开后将断开语音和联机。','',`<button class="button" data-action="modal-close">继续游戏</button><button class="button danger" data-action="confirm-leave">离开房间</button>`)}
 else if(a==='confirm-leave'){leaveRoom()}
 else if(a==='audio-settings'){state.view='settings';state.settingsTab='voice';closeModal();render()}
 else if(a==='settings-tab'){state.settingsTab=b.dataset.tab;closeModal();render()}
 else if(a==='device-test'){toast('仅演示设备测试入口，未采集或播放真实音频。')}
 else if(a==='copy-ip'){try{await navigator.clipboard.writeText(b.dataset.ip);toast(`已复制 ${b.dataset.ip}，请在游戏中直接连接。`)}catch{toast(`请手动复制：${b.dataset.ip}`)}}
 else if(a==='invite-friend'){inviteModal(b.dataset.name)}
 else if(a==='confirm-invite'){const name=document.getElementById('invite-name').value,roomId=document.getElementById('invite-room').value;if(!name){toast('请先添加好友。');return}if(!createInvitation(name,rooms.find(room=>room.id===roomId)?.groupId,roomId))return;closeModal();toast(`已向 ${name} 发送组队邀请（模拟）。`)}
 else if(a==='friend-filter'){state.friendFilter=b.dataset.filter;render()}
 else if(a==='friend-profile'){const n=b.dataset.name,p=people[n];if(!p)return;openModal(n,'玩家资料卡',`<div style="display:flex;align-items:center;gap:14px;margin-bottom:18px">${avatar(n)}<div><strong>${n}</strong><p style="color:var(--muted);font-size:12px;margin:5px 0">${p.id} · ${esc(personStatus(n))}</p></div></div><div class="modal-note">共同群组：${groups.filter(g=>g.members.includes(n)&&g.members.includes(me)).map(g=>esc(g.name)).join('、')||'无'}</div>`,`<button class="button danger" data-action="remove-friend" data-name="${n}">删除好友</button><button class="button" data-action="copy-id" data-name="${n}">复制账号 ID</button><button class="button primary" data-action="invite-friend" data-name="${n}">邀请组队</button>`)}
 else if(a==='copy-id'){const id=people[b.dataset.name].id;try{await navigator.clipboard.writeText(id);toast(`账号 ID ${id} 已复制。`)}catch{toast(`账号 ID：${id}`)}}
 else if(a==='add-friend'){openModal('添加好友','通过已验证邮箱或账号 ID 搜索。','<div class="field"><label>邮箱 / 账号 ID</label><input id="friend-account" value="newplayer#1024"></div>',`<button class="button" data-action="modal-close">取消</button><button class="button primary" data-action="confirm-add-friend">发送申请</button>`)}
 else if(a==='confirm-add-friend'){const id=document.getElementById('friend-account').value.trim();if(!id)return;if(!state.outgoingRequests.includes(id))state.outgoingRequests.push(id);closeModal();toast(`已向 ${id} 发送好友申请（模拟）。`)}
 else if(a==='friend-requests'){openModal('待处理申请','接受或拒绝好友申请。',`${state.incomingRequests.map(n=>`<div class="friend-row" style="padding-left:0;padding-right:0">${avatar(n)}<div class="friend-copy"><strong>${n}</strong><small>希望添加你为好友</small></div><button class="button primary small" data-action="accept-request" data-name="${n}">接受</button><button class="button small" data-action="reject-request" data-name="${n}">拒绝</button></div>`).join('')||'<div class="empty-state">暂无待处理申请</div>'}<div class="modal-note">发出的申请：${state.outgoingRequests.map(esc).join('、')||'无'}</div>`)}
 else if(a==='accept-request'){const n=b.dataset.name;state.incomingRequests=state.incomingRequests.filter(x=>x!==n);if(!state.friends.includes(n))state.friends.push(n);closeModal();render();toast(`已添加 ${n} 为好友。`)}
 else if(a==='reject-request'){state.incomingRequests=state.incomingRequests.filter(n=>n!==b.dataset.name);closeModal();render();toast('已拒绝好友申请。')}
 else if(a==='remove-friend'){const n=b.dataset.name;openModal(`删除好友 ${n}？`,'删除后不再显示对方的在线与房间状态。','',`<button class="button" data-action="modal-close">取消</button><button class="button danger" data-action="confirm-remove-friend" data-name="${n}">确认删除</button>`)}
 else if(a==='confirm-remove-friend'){state.friends=state.friends.filter(n=>n!==b.dataset.name);closeModal();render();toast('好友已删除。')}
 else if(a==='open-group'){if(!isGroupMember(b.dataset.group)){toast('你已不在此群中。');return}state.groupId=b.dataset.group;state.view='groupChat';render()}
 else if(a==='create-group'){openModal('创建私密群组','不会出现在公开搜索，只通过邀请加入。','<div class="field"><label>群名称</label><input id="new-group-name" placeholder="给朋友们的小窝起个名字"></div><div class="field"><label>简介</label><textarea id="new-group-desc" placeholder="这个群用来做什么？"></textarea></div>',`<button class="button" data-action="modal-close">取消</button><button class="button primary" data-action="confirm-create-group">创建群组</button>`)}
 else if(a==='confirm-create-group'){const name=document.getElementById('new-group-name').value.trim();if(!name||name.length>60){toast('群名称须为 1–60 个字符。');return}const id='group-'+state.nextId++,desc=document.getElementById('new-group-desc').value.trim();groups.push({id,name,desc,icon:name[0],members:[me],owner:me,roles:{},roomIds:[],messages:[],audit:[]});state.groupId=id;state.view='groupChat';closeModal();render();toast('私密群组已创建（模拟）。')}
 else if(a==='group-manage'){groupManageModal()}
 else if(a==='player-settings'){const n=b.dataset.name,vol=state.memberVolumes[n]??70;openModal(`${esc(n)} · 语音`,'成员音量只影响本地接收。',`<div class="field"><label>成员音量 · <span id="member-volume-label">${vol}</span>%</label><input type="range" min="0" max="100" value="${vol}" data-input="member-volume" data-name="${n}"></div>`,`<button class="button primary" data-action="modal-close">完成</button>${canKickPlayer(currentRoom(),n)?`<button class="button danger" data-action="kick-player" data-name="${esc(n)}">移出房间</button>`:''}`)}
 else if(a==='delete-message'){openModal('删除这条消息？','删除后无法恢复。','',`<button class="button" data-action="modal-close">取消</button><button class="button danger" data-action="confirm-delete-message" data-scope="${b.dataset.scope}" data-id="${b.dataset.id}">确认删除</button>`)}
 else if(a==='confirm-delete-message'){const context=messageContext(b.dataset.scope),error=messageAccess(context);if(error){toast(error);return}const list=messageList(context),m=list?.find(m=>m.id===b.dataset.id);if(m){if(m.user!==me&&!canModerate(context.groupId)){toast('当前身份无权删除此消息。');return}if(m.user!==me)appendAudit(context.groupId,'代删消息',m.user);m.deleted=true;m.text='';if(m.media){URL.revokeObjectURL(m.media.url);delete m.media}}closeModal();render();toast('消息已删除。')}
 else if(a==='account-settings'||a==='profile'){state.view='settings';state.settingsTab='account';closeModal();render()}
 else if(a==='device-transfer'){openModal('转移活动设备？','语音和联机将转到另一台电脑，此电脑将离开房间。','',`<button class="button" data-action="modal-close">取消</button><button class="button primary" data-action="confirm-device-transfer">确认转移</button>`)}
 else if(a==='support-matrix'){state.view='settings';state.settingsTab='support';closeModal();render()}
 else if(a==='help'||a==='network-help'){helpModal(a==='network-help')}
 else if(a==='network-retry'||a==='voice-retry'){retryChannel(a==='network-retry'?'network':'voice')}
 else if(a==='toggle-setting'){state.settings[b.dataset.setting]=!state.settings[b.dataset.setting];render()}
 else if(a==='logout'){openModal('退出登录？',state.joined?'退出登录将离开当前房间，并断开语音和联机。':'','',`<button class="button" data-action="modal-close">取消</button><button class="button danger" data-action="confirm-logout">退出登录</button>`)}
 else if(a==='confirm-logout'){logout()}
 else if(a==='auth-mode'){state.authMode=b.dataset.mode;render()}
 else if(a==='modal-close'){closeModal()}
 else if(a==='backdrop'){if(e.target===b)closeModal()}
});
document.addEventListener('input',e=>{if(e.target.id==='media-caption'&&state.mediaDraft)state.mediaDraft.caption=e.target.value;if(e.target.dataset.input==='friend-search'){state.friendQuery=e.target.value;render();const input=document.querySelector('[data-input="friend-search"]');input.focus();input.setSelectionRange(input.value.length,input.value.length)}if(e.target.dataset.input==='volume'){state.volume=Number(e.target.value);document.getElementById('master-volume-label').textContent=`${state.volume}%`}if(e.target.dataset.input==='member-volume'){state.memberVolumes[e.target.dataset.name]=Number(e.target.value);document.getElementById('member-volume-label').textContent=e.target.value}if(e.target.dataset.input==='room-draft'&&state.roomId)state.drafts.room[state.roomId]=e.target.value;if(e.target.dataset.input==='group-draft'&&state.groupId)state.drafts.group[state.groupId]=e.target.value});
document.addEventListener('change',e=>{if(e.target.dataset.change==='input-device')state.settings.inputDevice=e.target.value;if(e.target.dataset.change==='output-device')state.settings.outputDevice=e.target.value;if(e.target.dataset.change==='media-file')selectMediaFile(e.target.files[0])});
document.addEventListener('scroll',e=>{if(e.target.classList?.contains('chat-scroll')&&state.roomId)state.chatScroll.room[state.roomId]=e.target.scrollTop;if(e.target.classList?.contains('group-chat-body')&&state.groupId)state.chatScroll.group[state.groupId]=e.target.scrollTop},true);
document.addEventListener('submit',e=>{const scope=e.target.dataset.form==='room-message'?'room':e.target.dataset.form==='group-message'?'group':null;if(scope){e.preventDefault();sendTextMessage(scope)}});
document.addEventListener('keydown',handleModalKey);
initializePrototype();
render();
